import pandas as pd

def find_top_scoring_students_ii(students: pd.DataFrame, courses: pd.DataFrame, enrollments: pd.DataFrame) -> pd.DataFrame:
    if students.empty or courses.empty or enrollments.empty:
        return pd.DataFrame(columns=['student_id'])

    mand_counts = courses[courses['mandatory'] == 'Yes'].groupby('major')['course_id'].count().to_dict()

    merged = students.merge(enrollments, on='student_id').merge(courses, on='course_id', suffixes=('_student', '_course'))

    qualified = []
    for sid, group in merged.groupby('student_id'):
        major = group['major_student'].iloc[0]
        req_mand = mand_counts.get(major, 0)

        mand_a = len(group[(group['major_course'] == major) & (group['mandatory'] == 'Yes') & (group['grade'] == 'A')])
        if mand_a < req_mand:
            continue

        elec_cnt = len(group[(group['major_course'] == major) & (group['mandatory'] == 'No') & (group['grade'].isin(['A', 'B']))])
        if elec_cnt < 2:
            continue

        total_weighted_gpa = (group['gpa'] * group['credits']).sum()
        total_credits = group['credits'].sum()
        avg_gpa = round(total_weighted_gpa / total_credits, 2)
        if avg_gpa >= 2.5:
            qualified.append(sid)

    res = pd.DataFrame({'student_id': sorted(qualified)})
    return res
